        if (!isDarkEventActive)
        {
            if (eventTimer >= EVENT_INTERVAL)
            {
                // Start Dark Event
                ToggleDarkness(true);
                isDarkEventActive = true;
                // Reset timer to count duration of darkness
                eventTimer = 0f;
            }
        }
        else
        {
            if (eventTimer >= DARK_DURATION)
            {
                // End Dark Event
                ToggleDarkness(false);

                // Trigger Shuffle Event
