    public static void Execute()
    {
        CreateBooster("Booster_Shield", BoosterType.Shield, "BoosterShieldMat", PrimitiveType.Sphere);
        CreateBooster("Booster_Slow", BoosterType.Slow, "BoosterSlowMat", PrimitiveType.Cube);
        CreateBooster("Booster_SpeedUp", BoosterType.SpeedUp, "BoosterSpeedMat", PrimitiveType.Capsule);
        CreateBooster("Booster_Trap", BoosterType.Trap, "BoosterTrapMat", PrimitiveType.Cube);
        CreateBooster("Booster_FreezeAll", BoosterType.FreezeAllOther, "BoosterFreezeAllMat", PrimitiveType.Cylinder);
    }

    static void CreateBooster(string name, BoosterType type, string matName, PrimitiveType primitive)
    {
        GameObject go = GameObject.CreatePrimitive(primitive);
        go.name = name;

        // Add Booster component
        Booster booster = go.AddComponent<Booster>();
        booster.type = type;

        // Assign material
        Renderer renderer = go.GetComponent<Renderer>();
        Material mat = AssetDatabase.LoadAssetAtPath<Material>($"Assets/Materials/{matName}.mat");
        if (mat != null) renderer.material = mat;

        // Ensure collider is trigger
        Collider col = go.GetComponent<Collider>();
        if (col != null) col.isTrigger = true;

        // Save as prefab
        PrefabUtility.SaveAsPrefabAsset(go, $"Assets/Prefabs/{name}.prefab");

        // Cleanup
        Object.DestroyImmediate(go);
    }
}

