        config.mapPrefabs[0] = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Map/Map1.prefab");
        config.mapPrefabs[1] = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Map/Map2.prefab");
