            if (config.mapPrefabs[i] != null)
            {
                Debug.Log($"Assigned Map Prefab {i}: {config.mapPrefabs[i].name}");
            }
            else
            {
                Debug.LogError($"Map Prefab {i} not found!");
            }
        }

        EditorUtility.SetDirty(config);
        AssetDatabase.SaveAssets();
